create or replace function spiritual.equation_of_time (d timestamp) returns numeric language sql immutable as $$ select 229.2 * (0.000075 + 0.001868 * cos(radians(360.0 / 365.0 * (extract(doy from d) - 1))) - 0.032077 * sin(radians(360.0 / 365.0 * (extract(doy from d) - 1))) - 0.014615 * cos(radians(720.0 / 365.0 * (extract(doy from d) - 1))) - 0.04089 * sin(radians(720.0 / 365.0 * (extract(doy from d) - 1)))); $$;
